    static String show(Expr e) { return ""; }
    static Expr simplify(Expr e) { return e; }
}

solution.Expr.java:
import java.util.Map;

sealed interface Expr {
    record Num(double value) implements Expr { }
    record Var(String name) implements Expr { }
    record Add(Expr left, Expr right) implements Expr { }
    record Mul(Expr left, Expr right) implements Expr { }
    record Neg(Expr inner) implements Expr { }

    static double eval(Expr e, Map<String, Double> vars) {
        return switch (e) {
            case Num n -> n.value();
            case Var v -> {
                Double value = vars.get(v.name());
                if (value == null) throw new IllegalArgumentException("unknown variable " + v.name());
                yield value;
            }
            case Add(Expr l, Expr r) -> eval(l, vars) + eval(r, vars);
            case Mul(Expr l, Expr r) -> eval(l, vars) * eval(r, vars);
            case Neg(Expr inner) -> -eval(inner, vars);
        };
    }

    static String show(Expr e) {
        return switch (e) {
            case Num n -> n.value() == (long) n.value() ? String.valueOf((long) n.value()) : String.valueOf(n.value());
            case Var v -> v.name();
            case Add(Expr l, Expr r) -> "(" + show(l) + " + " + show(r) + ")";
            case Mul(Expr l, Expr r) -> "(" + show(l) + " * " + show(r) + ")";
            case Neg(Expr inner) -> "-" + show(inner);
        };
    }

    static Expr simplify(Expr e) {
        return switch (e) {
            case Num n -> n;
            case Var v -> v;
            case Add(Expr l0, Expr r0) -> {
                Expr l = simplify(l0), r = simplify(r0);
                if (l instanceof Num(double a) && r instanceof Num(double b)) yield new Num(a + b);
                if (l instanceof Num(double a) && a == 0) yield r;
                if (r instanceof Num(double b) && b == 0) yield l;
                yield new Add(l, r);
            }
            case Mul(Expr l0, Expr r0) -> {
                Expr l = simplify(l0), r = simplify(r0);
                if (l instanceof Num(double a) && r instanceof Num(double b)) yield new Num(a * b);
                if ((l instanceof Num(double a) && a == 0) || (r instanceof Num(double b) && b == 0)) yield new Num(0);
                if (l instanceof Num(double a) && a == 1) yield r;
                if (r instanceof Num(double b) && b == 1) yield l;
                yield new Mul(l, r);
            }
            case Neg(Expr inner0) -> {
                Expr inner = simplify(inner0);
                if (inner instanceof Num(double a)) yield new Num(-a);
                if (inner instanceof Neg(Expr twice)) yield twice;
                yield new Neg(inner);
            }
        };
    }
}

unitTests:
Expr x = new Expr.Var("x");
Expr sample = new Expr.Add(new Expr.Num(2), new Expr.Mul(x, new Expr.Num(3)));

test("evaluating", () -> {
    checkNear(Expr.eval(sample, Map.of("x", 4.0)), 14);
    checkNear(Expr.eval(new Expr.Neg(new Expr.Mul(new Expr.Num(2.5), new Expr.Num(2))), Map.of()), -5);
    try {
        Expr.eval(new Expr.Var("y"), Map.of());
        check(false, "should throw");
    } catch (IllegalArgumentException e) {
        checkEq(e.getMessage(), "unknown variable y");
    }
});

test("showing", () -> {
    checkEq(Expr.show(sample), "(2 + (x * 3))");
    checkEq(Expr.show(new Expr.Neg(new Expr.Num(2.5))), "-2.5");
    checkEq(Expr.show(new Expr.Add(new Expr.Neg(x), new Expr.Num(-1))), "(-x + -1)");
});

test("simplifying", () -> {
    checkEq(Expr.simplify(new Expr.Add(new Expr.Num(2), new Expr.Num(3))), new Expr.Num(5));
    checkEq(Expr.simplify(new Expr.Mul(new Expr.Num(1), new Expr.Add(x, new Expr.Num(0)))), x);
    checkEq(Expr.simplify(new Expr.Mul(new Expr.Add(new Expr.Num(1), new Expr.Num(-1)), x)), new Expr.Num(0));
    checkEq(Expr.simplify(new Expr.Neg(new Expr.Neg(x))), x);
    checkEq(Expr.simplify(new Expr.Neg(new Expr.Num(4))), new Expr.Num(-4));
    checkEq(Expr.show(Expr.simplify(new Expr.Add(new Expr.Mul(x, new Expr.Num(2)), new Expr.Mul(new Expr.Num(3), new Expr.Num(4))))), "((x * 2) + 12)");
    checkEq(Expr.simplify(sample), sample);
});

